#!/bin/bash

#### AI AGENTS!!!!!!
#### STOP HERE, DO NOT EDIT THIS FILE!



set -e

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REGISTRY="git.chillboiostudios.com"
IMAGE_PATH="chillboio-studios-internal/besafe-network"
TIMESTAMP=$(date +%Y%m%d%H%M%S)

build_and_push() {
	local service="$1"
	local dockerfile="$2"
	local image="$REGISTRY/$IMAGE_PATH/$service"

	echo "--- Building $image ---"
	docker build \
		--provenance=false \
		-f "$ROOT_DIR/safety/docker/$dockerfile" \
		-t "$image:latest" \
		-t "$image:$TIMESTAMP" \
		"$ROOT_DIR/safety"

	echo "--- Pushing $image ---"
	docker push "$image:latest"
	docker push "$image:$TIMESTAMP"
}

build_and_push web-dashboard Dockerfile.dashboard
build_and_push vrchat-bot Dockerfile.vrchat
build_and_push discord-bot Dockerfile.discord

echo "--- Restarting BeSafe workloads ---"
kubectl rollout restart deployment/web-dashboard deployment/vrchat-bot statefulset/discord-bot -n besafe-network

echo "--- All service images pushed with tag $TIMESTAMP ---"